    public static void main(String[] args) throws IOException {
        String outputPath = "D:\\Work_Space\\ECHO_ERP\\SIRONPDFGENERATION\\SIRONPDFGENERATION\\full_arabic_test.pdf";

        // 1. Initialize PDF document
        PdfWriter writer = new PdfWriter(outputPath);
        PdfDocument pdf = new PdfDocument(writer);
        Document document = new Document(pdf);
        LanguageProcessor al = new ArabicLigaturizer();
        PdfFont arabicFont;
        try {
            arabicFont = PdfFontFactory.createFont(
                    "D:\\Work_Space\\ECHO_ERP\\SIRONPDFGENERATION\\SIRONPDFGENERATION\\src\\main\\resources\\NotoSansArabic-Bold.ttf",
                    PdfEncodings.IDENTITY_H,
                    true
            );
        } catch (IOException e) {
            System.err.println("Arabic font Amiri not found, falling back to default (may not render correctly)");
            arabicFont = PdfFontFactory.createFont();
        }

        // 3. Add content with RTL support
        document.add(new Paragraph("Arabic Legal Document")
                .setFont(arabicFont)
                .setFontSize(16)
                .setBold()
                .setTextAlignment(TextAlignment.CENTER));

        // Split text into paragraphs by semicolons
        String[] paragraphs = FULL_ARABIC_TEXT.split(";");
        for (String para : paragraphs) {
            if (!para.trim().isEmpty()) {
                document.add(new Paragraph(al.process(para.trim()))
                        .setFont(arabicFont)
                        .setFontSize(10)
                        .setTextAlignment(TextAlignment.RIGHT)
                        .setBaseDirection(com.itextpdf.layout.property.BaseDirection.RIGHT_TO_LEFT)
                        .setMarginBottom(15));
            }
        }

        // 4. Close document
        document.close();
        System.out.println("Generated PDF with Arabic text at: " + outputPath);
    }
